/// <summary>
/// The <c>AVAPrintContainerLabelHelper</c> represents a class with helpful function on container label process
/// </summary>
/// <remarks>
/// AVA_7303_9393_ContainerLabelOnClose
/// </remarks>
class AVAPrintContainerLabelHelper
{

}

Method.Source:
/// <summary>
/// call the Print of the container after check to print
/// </summary>
/// <param name = "_closeContainerProfile">
/// The current WHSCloseContainerProfile record
/// </param>
public static void checkAndPrintContainerLabel(WHSCloseContainerProfile _closeContainerProfile)
{
    AVACloseContainerUsingParamIDisposable  avaCloseContainerUsingParamIDisposable;
    WHSContainerTable                       avaWHSContainerTable;


    avaCloseContainerUsingParamIDisposable = AVACloseContainerUsingParamIDisposable::current();

    if (avaCloseContainerUsingParamIDisposable
     && avaCloseContainerUsingParamIDisposable.closeContainerParams)
    {
        if (_closeContainerProfile.AVAPrintContainerLabel == NoYes::Yes)
        {
            avaWHSContainerTable = WHSContainerTable::find(avaCloseContainerUsingParamIDisposable.closeContainerParams.parmShipmentId(),
                                                           avaCloseContainerUsingParamIDisposable.closeContainerParams.parmContainerId());


            if (avaWHSContainerTable)
            {
                AVAPrintContainerLabelHelper::printContainerLabel(avaWHSContainerTable);
            }
        }
    }
}

/// <summary>
/// Print the container label and wrap it with the AVAContainerLabelPrintIDisposable
/// </summary>
/// <param name = "_containerTable">
/// The current WHSContainerTable record
/// </param>
public static void printContainerLabel(WHSContainerTable _containerTable)
{
    AVAPrintContainerLabelHelper  printContainerLabelHelper;

    printContainerLabelHelper = AVAPrintContainerLabelHelper::construct();

    using (AVAContainerLabelPrintIDisposable instance = AVAContainerLabelPrintIDisposable::construct())
    {
        instance.showDialog = false;

        printContainerLabelHelper.callMenuFunction(_containerTable);
    }
}

private void callMenuFunction(WHSContainerTable _containerTable)
{
    Args            args;
    MenuFunction    menuFunction;

    menuFunction    = new MenuFunction(menuitemDisplayStr(WHSContainerLabelPrint), MenuItemType::Display);
    args            = new Args(menuFunction.object());

    args.caller(this);
    args.record(_containerTable);

    menuFunction.run(args);
}

public static AVAPrintContainerLabelHelper construct()
{
    return new AVAPrintContainerLabelHelper();
}
